import firstImage from "../img/firstumage.png";
import doubleImage from "../img/doubleimage.png";
import tripleImage from "../img/tripleimage.png";
import lastImage from "../img/lastimage.png";

function PetsSection() {
  return (
    <section className="pets-section" id="about">
      <h2 className="pets-title">Interacting with our pets</h2>

      <div className="pets-gallery">
        <article className="pets-card">
          {/* ФОТО 1 — собака в костюме привидения */}
          <img src={firstImage} alt="Dog dressed as a ghost" />
          <p>Rescue pups pose as ghosts in festive photo shoot</p>
        </article>

        <article className="pets-card">
          {/* ФОТО 2 — кот и утренний кофе */}
          <img src={doubleImage} alt="Cat interrupting morning coffee" />
          <p>Cat interrupts morning coffee on sunny Washington morning</p>
        </article>

        <article className="pets-card">
          {/* ФОТО 3 — ребёнок и собака */}
          <img src={tripleImage} alt="Child playing with a dog" />
          <p>New study finds dogs pay more attention to women</p>
        </article>

        <article className="pets-card">
          {/* ФОТО 4 — собаку гладят */}
          <img src={lastImage} alt="Dog being petted" />
          <p>Petting dogs gives health benefits, even if they are not yours</p>
        </article>
      </div>
    </section>
  );
}

export default PetsSection;
